DOWNGRADE_PREFLIGHT = "LOCK TABLE change_order_records,change_approval_records,change_implementation_captures,change_implementation_records,controlled_change_policy_facts,controlled_change_policy_currents,controlled_change_selection_facts,controlled_change_selection_currents,change_request_versions,confirmations,action_receipts IN SHARE ROW EXCLUSIVE MODE;\nDO $$ BEGIN IF EXISTS(SELECT 1 FROM change_order_records) OR EXISTS(SELECT 1 FROM change_approval_records) OR EXISTS(SELECT 1 FROM change_implementation_captures) OR EXISTS(SELECT 1 FROM change_implementation_records) OR EXISTS(SELECT 1 FROM controlled_change_policy_facts) OR EXISTS(SELECT 1 FROM controlled_change_policy_currents) OR EXISTS(SELECT 1 FROM controlled_change_selection_facts) OR EXISTS(SELECT 1 FROM controlled_change_selection_currents) OR EXISTS(SELECT 1 FROM change_request_versions WHERE operation IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide','change.policy.import')) OR EXISTS(SELECT 1 FROM action_receipts WHERE operation IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide','change.policy.import')) OR EXISTS(SELECT 1 FROM confirmations WHERE operation IN ('change.order.prepare','change.order.approve','change.implementation.record','change.selection.decide','change.policy.import')) THEN RAISE EXCEPTION 'retained change history prevents downgrade'; END IF; END $$;"


def replace_checks(op, actual_check_names, expressions):
    if type(actual_check_names) is not tuple or len(actual_check_names) != 3:
        raise RuntimeError("Root must provide three exact verified old CHECK names")
    if len(set(actual_check_names)) != 3 or any(
        not isinstance(v, str) or not v.isidentifier() for v in actual_check_names
    ):
        raise RuntimeError("Exact immutable constraint names required")
    for name in actual_check_names:
        op.drop_constraint(name, "change_request_versions", type_="check")
    for i, expression in enumerate(expressions):
        op.create_check_constraint(
            f"ck_change_order_boundary_{i}", "change_request_versions", expression
        )


def upgrade_candidate(
    op, *, actual_head, allocated_revision, verified_check_names, verified_function_sha256
):
    # Arguments are Root-verified actual DB facts, not a public caller assertion.
    if (
        actual_head != EXPECTED_PARENT
        or not allocated_revision
        or allocated_revision == EXPECTED_PARENT
    ):
        raise RuntimeError("Actual head26 and a new Root-allocated revision required")
    expected = "77124b96289c401fcba480a25df8cb023a232729406f7fe2f2f234c594e3c06c"  # Replaced below by exact offline function hash.
    if verified_function_sha256 != expected:
        raise RuntimeError("Installed head26 receipt helper differs; rebase proposal")
    op.execute(PREFLIGHT)
    replace_checks(op, verified_check_names, NEW_CHECK_EXPRESSIONS)
    for sql in CREATE_TABLES:
        op.execute(sql)
    op.execute(EXTENDED_RECEIPT_HELPER)
    op.execute(ORDER_GUARDS)
    op.execute(CONTROLLED_GUARDS)
    for sql in PERMISSIONS:
        op.execute(sql)


def downgrade_candidate(op, *, verified_original_check_names):
    op.execute(DOWNGRADE_PREFLIGHT)
    for trigger, table in (
        ("change_receipt_atom", "action_receipts"),
        ("selection_proof_atom", "confirmations"),
        ("change_confirmation_retained", "confirmations"),
        ("change_proof_order_atom", "confirmations"),
        ("change_version_order_atom", "change_request_versions"),
    ):
        op.execute(f"DROP TRIGGER {trigger} ON {table}")
    for name in DROP_TABLES:
        op.drop_table(name)
    for signature in (
        "assert_controlled_change_atom(text,uuid,uuid)",
        "require_controlled_change_atom()",
        "protect_controlled_change_current()",
        "require_change_receipt_atom()",
        "require_selection_proof_atom()",
        "protect_change_confirmation()",
        "require_change_order_atom()",
        "require_change_order_parent_atom()",
        "require_change_order_proof_atom()",
        "protect_change_implementation_capture()",
    ):
        op.execute(f"DROP FUNCTION public.{signature}")
    op.execute(OLD_RECEIPT_HELPER)
    for i in range(3):
        op.drop_constraint(
            f"ck_change_order_boundary_{i}", "change_request_versions", type_="check"
        )
    if type(verified_original_check_names) is not tuple or len(verified_original_check_names) != 3:
        raise RuntimeError("Root original Check map required")
    for name, expression in zip(verified_original_check_names, OLD_CHECK_EXPRESSIONS, strict=True):
        op.create_check_constraint(name, "change_request_versions", expression)


VERIFIED_CHECK_NAMES = (
    "change_request_versions_check",
    "change_request_versions_operation_check",
    "change_request_versions_request_snapshot_check",
)
VERIFIED_CHECK_EXPRESSIONS = (
    "(((visibility)::text = ANY ((ARRAY['private'::character varying, 'product'::character varying])::text[])) AND ((status)::text = ANY ((ARRAY['draft'::character varying, 'analysis'::character varying])::text[])))",
    "((operation)::text = ANY ((ARRAY['change.request.create'::character varying, 'change.impact.compute'::character varying])::text[]))",
    "COALESCE(((request_snapshot -> 'orders'::text) = '[]'::jsonb), false)",
)


def upgrade():
    connection = op.get_bind()
    actual_head = connection.scalar(text("SELECT version_num FROM alembic_version"))
    actual_function = connection.scalar(
        text(
            "SELECT pg_get_functiondef('public.assert_quality_change_receipt(uuid,uuid,uuid,integer,text,text,uuid,text)'::regprocedure)"
        )
    )
    installed_checks = dict(
        connection.execute(
            text(
                "SELECT conname,pg_get_expr(conbin,conrelid) FROM pg_constraint WHERE conrelid='change_request_versions'::regclass AND contype='c'"
            )
        ).all()
    )
    if tuple(installed_checks.get(n) for n in VERIFIED_CHECK_NAMES) != VERIFIED_CHECK_EXPRESSIONS:
        raise RuntimeError("Exact predecessor checks changed; explicit rebase required")
    upgrade_candidate(
        op,
        actual_head=actual_head,
        allocated_revision=revision,
        verified_check_names=VERIFIED_CHECK_NAMES,
        verified_function_sha256=hashlib.sha256(actual_function.encode()).hexdigest(),
    )


def downgrade():
    downgrade_candidate(op, verified_original_check_names=VERIFIED_CHECK_NAMES)
